from pathlib import Path
import hashlib,re,json
b=Path('reference/step-00-input/baseline-filtered')
manifest={n:h for n,h in re.findall(r'\\| ([\\w.-]+) \\| ([0-9a-f]{64}) \\|',(b/'provenance-filtered.md').read_text())}
for n,h in manifest.items():
 p=b/n; actual=hashlib.sha256(p.read_bytes()).hexdigest(); print(n,actual,'MATCH' if actual==h else 'MISMATCH')
for n in ['provenance.md','provenance-filtered.md','scope-filter.diff']:
 print(n,hashlib.sha256((b/n).read_bytes()).hexdigest())
for n in ['input/README.md','reference/step-00-input/provenance.md']:
 print(n,hashlib.sha256(Path(n).read_bytes()).hexdigest())
rows=[x.split('|')[1].strip() for x in (b/'us-initial.md').read_text().splitlines() if x.startswith('| US-')]
print('US ROWS',len(rows),rows)
for n in ['flow.md','state-machine.md','structure.md']:
 lines=(b/n).read_text().splitlines(); print('\\nFILE',n)
 for i,line in enumerate(lines,1):
  for needle in ['US-14 จัดการ','รอลูกค้าตัดสินใจ']:
   if needle in line:
    j=line.index(needle); print('LEAK',i, line[max(0,j-100):j+200])
 print('HEAD', '\\n'.join(lines[:22]))
 print('LINKS',sorted(set(re.findall(r'\\]\\((["'^)]+)'"\\)', '\\n'.join(lines)))))
print('\\nDIFF HEADER')
for line in (b/'scope-filter.diff').read_text().splitlines():
 if line.startswith(('---','+++','@@')): print(line)
