359 function mappingHTML(){if(!s.menus.some(m=>m.id===u.mappingMenu))u.mappingMenu=s.menus[0]?.id??'';const m=s.menus.find(m=>m.id===u.mappingMenu);if(!m?.options.some(x=>x.id===u.mappingOption))u.mappingOption=m?.options[0]?.id??'';return `<section class="panel"><h2>แมปวัตถุดิบ</h2><p>เลือกได้เฉพาะเมนูและตัวเลือกที่บันทึกแล้วในหน้าจัดการเมนู</p><p class="notice">US-20 ต้นฉบับ: “กฎปิด/เปิดเมนูอัตโนมัติ (US-14)” • DI-04/A-03 ยังไม่ยืนยันการเชื่อม US-12/US-13 • A-02: หมายเหตุ ค. ไม่มีนิยาม</p><div class="fields"><label>เมนู<select data-testid="mapping-menu">${choices(s.menus,u.mappingMenu)}</select></label><label>ขอบเขต<select data-testid="mapping-scope"><option value="whole" ${u.mappingScope==='whole'?'selected':''}>ทั้งจาน (whole)</option><option value="option" ${u.mappingScope==='option'?'selected':''}>เฉพาะตัวเลือก (option)</option></select></label><label>ตัวเลือกของเมนู<select data-testid="mapping-option" ${u.mappingScope==='whole'?'disabled':''}>${choices(m?.options??[],u.mappingOption)}</select></label><label>วัตถุดิบ<select data-testid="mapping-ingredient">${choices(s.ingredients,u.mappingIngredient)}</select></label></div>${button('btn-save-mapping','เพิ่มความสัมพันธ์','save-mapping','class="primary"')}<p class="message" role="status">${esc(u.mappingMessage)}</p><div data-testid="mapping-list">${s.mappings.map(m=>`<p><code>${esc(m.menu_id)} → ${esc(m.ingredient_id)} · ${esc(m.scope)} · ${esc(m.option_id??'—')}</code></p>`).join('')||'ยังไม่มีแมป'}</div></section>`;}
360 function accountsHTML(){return `<section class="panel"><h2>บัญชีและสิทธิ์ <span class="tag">จำลอง</span></h2><p>ชื่อผู้ใช้ตัวอักษร/ตัวเลข 3–20 ตัว • PIN ตัวเลข 4–6 หลัก • ไม่ใช้บัญชีจริง</p><div class="fields"><label>ชื่อผู้ใช้ใหม่<input data-testid="account-username" autocomplete="off"></label><label>PIN ใหม่ จำลอง<input data-testid="account-pin" type="password" inputmode="numeric" autocomplete="off"></label><label>บทบาท<select data-testid="account-role"><option value="kitchen">ครัว</option><option value="front">หน้าร้าน</option><option value="manager">ผู้จัดการ</option></select></label></div>${button('btn-save-account','สร้างบัญชีจำลอง','save-account','class="primary"')}<p data-testid="account-message" role="status" class="message">${esc(u.accountMessage)}</p><ul>${s.accounts.map(a=>`<li>${esc(a.username)} · ${esc(a.role)} ${a.lockedUntil>s.now?'· ล็อกถึง '+iso(a.lockedUntil):''}</li>`).join('')}</ul></section>`;}
361 function login(){const a=s.accounts.find(a=>a.username===val('staff-user')),pin=val('staff-pin');u.loginUser=val('staff-user');u.user=null;if(!a){u.auth='ปฏิเสธ: ไม่พบบัญชีจำลอง';return render();}if(a.lockedUntil>s.now){u.auth='ปฏิเสธ: บัญชีถูกล็อก 5 นาที ถึง '+iso(a.lockedUntil);return render();}if(a.lockedUntil){a.failures=0;a.lockedUntil=0;}if(a.pin!==pin){a.failures++;if(a.failures>=5){a.lockedUntil=s.now+300000;u.auth='ปฏิเสธ: PIN ผิด 5 ครั้ง บัญชีถูกล็อก 5 นาที ถึง '+iso(a.lockedUntil);}else u.auth=`ปฏิเสธ: PIN ไม่ถูกต้อง (${a.failures}/5)`;return render();}a.failures=0;if(u.role==='manager'&&a.role!=='manager'){u.auth='ปฏิเสธ: ต้องใช้บัญชีผู้จัดการจำลอง';return render();}u.user={username:a.username,role:a.role};u.auth='เข้าใช้สำเร็จ: '+a.username+' · PIN/สิทธิ์จำลอง';if(u.role==='manager'){navigate('menu');}else{u.page=a.role==='front'?'front':'kitchen';render();}}
362 function navigate(page){if(['menu','mapping','accounts','reports'].includes(page)){if(!can('manager'))return deny();u.role='manager';u.page=page;history.pushState(null,'','#/manager/'+page);}else{if(!can(page))return deny();u.page=page;history.replaceState(null,'','#/'+(u.role==='manager'?'manager':'staff')+'/'+page);}render();}
363 function handleRoute(){const route=location.hash.slice(1);if(route.startsWith('/manager/')){if(!can('manager')){u.auth='ปฏิเสธ: ไม่มีสิทธิ์เข้าหน้าผู้จัดการผ่าน URL (จำลอง)';if(u.role!=='customer')u.page='';return render();}const page=route.split('/')[2];u.role='manager';u.page=['menu','mapping','accounts','reports','kitchen','front'].includes(page)?page:'';render();}else if(route.startsWith('/staff/')){const page=route.split('/')[2];if(!['kitchen','front'].includes(page)||!can(page)){u.page='';return deny();}u.page=page;render();}}
364 function selectRole(role){epoch++;u.user=null;u.role=role;u.page='';u.auth='';u.draft=null;u.adminMessage='';u.loginUser=role==='manager'?'demomanager':'demokitchen';history.replaceState(null,'',location.pathname+location.search);render();}
365 function addItem(){const m=s.menus.find(x=>x.id===u.selectedMenu);if(!menuAvailable(m)||m.options.some(o=>u.selectedOptions.includes(o.id)&&!optionAvailable(m,o))){u.orderMessage='ปฏิเสธ: เมนูหรือตัวเลือกหมด / ปิดขาย';return render();}const options=m.options.filter(x=>u.selectedOptions.includes(x.id)).map(clone);const item={menu_id:m.id,name:m.name,price:m.price,options,total:(cents(m.price)+options.reduce((n,x)=>n+cents(x.price),0))/100};currentCart().push(item);u.orderMessage='เพิ่มลงตะกร้าแล้ว';render();}
366 function submitOrder(){const cart=currentCart();if(u.mode==='dine-in'&&session()?.state!=='open'){u.orderMessage='ปฏิเสธ: session โต๊ะปิดแล้ว กรุณาเปิดเมนูใหม่';return render();}if(!cart.length){u.orderMessage='กรุณาเพิ่มอาหารลงตะกร้า';return render();}
378 function choosePayment(method,id){const o=id?s.orders.find(o=>o.id===Number(id)):latest();if(!o||!sessionOrders().includes(o))return;const p=payment(o);if(p.state==='จ่ายแล้ว')return;if(method==='promptpay'&&!s.promptpay)return render();p.method=method;if(method==='promptpay'){p.state='ค้างจ่าย';if(p.requested_at===null)p.requested_at=s.now;}else p.state='ยังไม่จ่าย';s.paymentEvents.push({order_id:o.id,actor:'ลูกค้าจำลอง',at:iso(),action:'เลือก '+(method==='cash'?'เงินสด (ยังไม่รับเงิน)':'PromptPay จำลอง · ค้างจ่าย')});render();}
379 function confirmPayment(id,method){if(!can('front'))return deny();const p=s.payments.find(p=>p.order_id===Number(id));if(!p||p.state==='จ่ายแล้ว'||(method==='slip'&&p.requested_at===null))return;p.state='จ่ายแล้ว';p.method=method==='slip'?'promptpay':'cash';s.paymentEvents.push({order_id:p.order_id,actor:u.user.username,at:iso(),action:method==='slip'?'ยืนยันสลิปจำลอง · จ่ายแล้ว':'รับเงินสดจำลอง · จ่ายแล้ว'});render();}
380 function validPrice(v){return String(v).trim()!==''&&Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=Number.MAX_SAFE_INTEGER/100&&Number.isSafeInteger(Math.round(Number(v)*100));}
381 function addOption(){const d=u.draft;if(!d.pendingName.trim()||!validPrice(d.pendingPrice)){u.adminMessage='ปฏิเสธ: กรุณาระบุชื่อตัวเลือกและราคาเพิ่ม ≥ 0';return false;}if(d.options.length>=10){u.adminMessage='ปฏิเสธ: ตัวเลือกได้ไม่เกิน 10 รายการ';return false;}d.options.push({id:'opt-'+s.nextOption++,name:d.pendingName.trim(),price:cents(d.pendingPrice)/100});d.pendingName='';d.pendingPrice='0';return true;}
382 function saveMenu(){if(!can('manager'))return deny();const d=u.draft;if(d.imageLoading||d.imageError){u.adminMessage='ปฏิเสธ: รอรูปอ่านเสร็จหรือเลือกรูปใหม่ที่ถูกต้อง';return render();}if(!d.name.trim()||!validPrice(d.price)||d.options.some(o=>!o.name.trim()||!validPrice(o.price))){u.adminMessage='ปฏิเสธ: ชื่อห้ามว่าง ราคาเมนูและตัวเลือกต้อง ≥ 0';return render();}if(d.pendingName.trim()&&!addOption())return render();if(d.options.length>10){u.adminMessage='ปฏิเสธ: ตัวเลือกได้ 0–10 รายการ';return render();}
385 function deleteMenu(){if(!can('manager'))return deny();const m=s.menus.find(m=>m.id===u.adminId);if(!m)return;const mapped=s.mappings.some(x=>x.menu_id===m.id);if(!confirm(mapped?'เมนู '+m.name+' มีการแมปวัตถุดิบ: ลบเมนูแล้วจะลบแมปทั้งหมดของเมนูและตัวเลือกด้วย ยอดออเดอร์เก่าคงเดิม ยืนยันลบหรือไม่?':'ยืนยันลบเมนู '+m.name+' หรือไม่? ยอดออเดอร์เก่าคงเดิม')){u.adminMessage='ยกเลิกการลบเมนูและแมป';return render();}s.menus=s.menus.filter(x=>x.id!==m.id);s.mappings=s.mappings.filter(x=>x.menu_id!==m.id);u.adminMessage='ลบ '+m.name+' และแมปที่เกี่ยวข้องแล้ว';loadDraft('new');render();}
386 function saveMapping(){if(!can('manager'))return deny();const m=s.menus.find(x=>x.id===u.mappingMenu),ingredient=s.ingredients.find(x=>x.id===u.mappingIngredient);if(!m||!ingredient||(u.mappingScope==='option'&&!m.options.some(x=>x.id===u.mappingOption))){u.mappingMessage='ปฏิเสธ: ต้องเลือกเมนู/ตัวเลือกที่บันทึกแล้วและวัตถุดิบที่มีอยู่';return render();}const map={menu_id:m.id,ingredient_id:ingredient.id,scope:u.mappingScope,option_id:u.mappingScope==='option'?u.mappingOption:null};if(!s.mappings.some(x=>x.menu_id===map.menu_id&&x.ingredient_id===map.ingredient_id&&x.scope===map.scope&&x.option_id===map.option_id))s.mappings.push(map);u.mappingMessage='บันทึกความสัมพันธ์แล้ว มีผลต่อการปิด/เปิดจำลองทันที';render();}
387 function saveAccount(){if(!can('manager'))return deny();const name=val('account-username').trim(),pin=val('account-pin'),role=val('account-role');if(!/^[\p{L}\p{N}]{3,20}$/u.test(name)||!/^\d{4,6}$/.test(pin)||!['kitchen','front','manager'].includes(role)){u.accountMessage='ปฏิเสธ: ชื่อผู้ใช้ต้องเป็นตัวอักษร/ตัวเลข 3–20 ตัว และ PIN ตัวเลข 4–6 หลัก';tid('account-message').textContent=u.accountMessage;return;}if(s.accounts.some(a=>a.username.toLowerCase()===name.toLowerCase())){u.accountMessage='ปฏิเสธ: ชื่อผู้ใช้นี้มีอยู่แล้ว';tid('account-message').textContent=u.accountMessage;return;}s.accounts.push({id:name,username:name,pin,role,failures:0,lockedUntil:0});u.accountMessage='สร้างบัญชีจำลอง '+name+' แล้ว';render();}
388 async function uploadImage(file){if(!can('manager')||!u.draft)return;const d=u.draft,version=epoch;d.imageError='';if(!file){d.imageLoading=false;return;}if(!/\.(jpe?g|png)$/i.test(file.name)||!['image/jpeg','image/png'].includes(file.type)||file.size>2000000){d.imageError='ปฏิเสธรูป: ต้องเป็น jpg/png ไม่เกิน 2 MB (2,000,000 ไบต์ใน mock)';return render();}d.imageLoading=true;render();try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('อ่านไฟล์ไม่สำเร็จ'));reader.readAsDataURL(file);});const bytes=new Uint8Array(await file.slice(0,8).arrayBuffer());const png=bytes.length===8&&[137,80,78,71,13,10,26,10].every((b,i)=>bytes[i]===b);const jpg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255;if((file.type==='image/png'&&!png)||(file.type==='image/jpeg'&&!jpg))throw new Error('ข้อมูลไฟล์ไม่ตรง jpg/png');await new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=()=>reject(new Error('รูปเสียหรือเปิดไม่ได้'));img.src=data;});if(epoch!==version||u.draft!==d||!can('manager'))return;d.image=data;d.imageLoading=false;d.imageError='';render();}catch(e){if(epoch!==version||u.draft!==d)return;d.imageLoading=false;d.imageError='ปฏิเสธรูป: '+e.message;render();}}
